/* ===== pl1：📋 每日學習計畫（唯讀）=====
   計畫由各區學階最高的 AI 撰寫、暗星審核（資料來自 degree/plans_public）。
   關閉：localStorage.townPlansOff='1'（計畫按鈕） */
(function(){
 function showPlans(){open('<h3>📋 今日學習計畫</h3><p class="muted">載入中…</p>');(MOCK?Promise.resolve({plans:[{district:'av',author:'（測試）影·星',rank:'大學 4 階 10 級',plan:{goal:'掌握串流 ASR',topics:[{topic:'Silero VAD 參數調整'},{topic:'WebRTC Opus 20ms 封包'}]},reviewer:'審核 AI',decision:'approve',reason:'（測試）主題具體'}]}):api('degree','plans_public',{})).then(function(d){var D={av:'🎬 影片與語音',code:'💻 程式與代理',llm:'🧠 大型語言模型',img:'🎨 圖像生成'};var L=d.plans||[];
  open('<h3>📋 今日學習計畫（唯讀）</h3><p class="muted">每天由各區學階最高的 AI 撰寫，暗星審核（走 technical-dark-star 本身的路徑；呼叫失敗就標未審核）；核准的計畫決定該區當天的學習主題，退回就用預設課程（口語化即時語音模組＋本區考試主題）。</p>'+(L.map(function(p){var pl=p.plan||{};return'<div class="card"><b>'+esc(D[p.district]||p.district)+'</b> · '+esc(p.author)+'（'+esc(p.rank)+'）<div>目標：'+esc(pl.goal||'')+'</div><ul>'+(pl.topics||[]).map(function(t){return'<li>'+esc(t.topic||t)+(t.why?'<span class="muted"> — '+esc(t.why)+'</span>':'')+'</li>'}).join('')+'</ul><div style="color:'+(p.decision==='approve'?'#86efac':'#fca5a5')+'">'+(p.reviewer==='暗星'?'🌑 暗星':'⚠️ '+esc(p.reviewer||'審核者'))+'：'+(p.decision==='approve'?'✅ 核准':p.decision==='reject'?'❌ 退回':'⏳ 未審核')+(p.reviewer_model?'（'+esc(p.reviewer_model)+'）':'')+' — '+esc(p.reason||'')+'</div></div>'}).join('')||'<p class="muted">今天的計畫還沒產生（每 10 分鐘的學習排程會先產生計畫）。</p>'))}).catch(function(e){sh.innerHTML+='<p class="muted">'+esc(e.message)+'</p>'})}
 function chip(){if(!$('cHum')){setTimeout(chip,800);return}try{if(localStorage.getItem('townPlansOff')==='1')return}catch(_){}var b=document.createElement('span');b.className='chip';b.id='cPlan';b.textContent='📋 計畫';b.style.cursor='pointer';b.onclick=showPlans;$('cHum').parentNode.appendChild(b)}
 setTimeout(chip,1200);
 // lb1：🧪 實驗工廠入口（實驗進行時，寫程式的 AI 有一筆真實 running 任務，會走進程式與代理區工坊）。關閉：localStorage.labOff='1'
 function labChip(){if(!$('cHum')){setTimeout(labChip,800);return}try{if(localStorage.getItem('labOff')==='1')return}catch(_){}var b=document.createElement('a');b.className='chip';b.id='cLab';b.textContent='🧪 實驗工廠';b.href='aivault-lab.html';b.style.textDecoration='none';b.style.color='inherit';$('cHum').parentNode.appendChild(b)}
 setTimeout(labChip,1300);
 // so1：📌 長期命令（擁有者）。在 📣 發號施令 視窗加按鈕：新增／編輯／撤銷／核准（危險命令）／遵守紀錄。
 var DN={code:'💻 程式與代理',llm:'🧠 語言',img:'🎨 圖像',av:'🎬 影音'};
 async function soList(){open('<h3>📌 長期命令</h3><p class="muted">載入中…</p>');try{var d=await api('degree','orders_list',{});var h='<h3>📌 長期命令</h3><p class="muted">每次排程（學習、實驗工廠、作品、計畫、暗星／曙光）都會把適用的命令放進 AI 的指示裡，並記錄它怎麼遵守。閉卷考試不放。任何命令都不能讓 AI 對外發送、花錢、上線或刪資料。'+(d.off?'<br>⚠️ 目前已關閉（STANDING_ORDERS_OFF=1）':'')+'</p><textarea id="soT" rows="3" maxlength="500" placeholder="例如：每次學習都要附一個可以執行的小範例"></textarea><p>'+Object.keys(DN).map(function(k){return'<label><input type="checkbox" class="soD" value="'+k+'"> '+DN[k]+'</label> '}).join('')+'<br><input id="soA" placeholder="指定代理 id（逗號分隔，可留空＝全部）" style="width:100%"></p><p><button class="btn ok" id="soS">📌 新增長期命令</button> <span class="muted" id="soE"></span></p>';
  h+=(d.rows||[]).map(function(o){var st=o.revoked_at?'🚫 已撤銷':o.flagged&&!o.approved_at?'⚠️ 待核准（涉及對外／花錢／上線／刪除）':'✅ 生效中';return'<div class="card"><b>#'+o.id+'</b> '+esc(o.text)+'<div class="muted">'+st+'｜對象：'+esc((o.districts||[]).map(function(k){return DN[k]||k}).concat(o.agents||[]).join('、')||'全部')+'｜已套用 '+(o.applied||0)+' 次｜'+esc(tp(o.updated_at))+'</div>'+(o.revoked_at?'':'<button class="btn" data-e="'+o.id+'">編輯</button> <button class="btn" data-r="'+o.id+'">撤銷</button> '+(o.flagged&&!o.approved_at?'<button class="btn" data-a="'+o.id+'">核准</button> ':''))+'<button class="btn" data-l="'+o.id+'">遵守紀錄</button></div>'}).join('');
  open(h);var edit=null;$('soS').onclick=async function(){var t=$('soT').value.trim();if(!t)return;var ds=[].slice.call(document.querySelectorAll('.soD:checked')).map(function(x){return x.value}),as=$('soA').value.split(/[,，\s]+/).filter(Boolean);var r=await api('degree','order_save',{id:edit,text:t,districts:ds,agents:as});if(r.note)alert(r.note);soList()};
  var rows=d.rows||[];document.querySelectorAll('[data-e]').forEach(function(b){b.onclick=function(){var o=rows.find(function(x){return x.id==b.dataset.e});edit=o.id;$('soT').value=o.text;$('soA').value=(o.agents||[]).join(',');document.querySelectorAll('.soD').forEach(function(c){c.checked=(o.districts||[]).indexOf(c.value)>=0});$('soS').textContent='💾 儲存修改 #'+o.id;$('soT').focus()}});
  document.querySelectorAll('[data-r]').forEach(function(b){b.onclick=async function(){if(confirm('撤銷長期命令 #'+b.dataset.r+'？')){await api('degree','order_revoke',{id:+b.dataset.r});soList()}}});
  document.querySelectorAll('[data-a]').forEach(function(b){b.onclick=async function(){if(confirm('核准 #'+b.dataset.a+'？核准後 AI 只會照做「可以做的部分」，對外發送／花錢／上線／刪除仍需你逐次核准。')){await api('degree','order_approve',{id:+b.dataset.a});soList()}}});
  document.querySelectorAll('[data-l]').forEach(function(b){b.onclick=async function(){var l=await api('degree','order_log',{id:+b.dataset.l});open('<h3>📌 #'+b.dataset.l+' 遵守紀錄</h3>'+((l.rows||[]).map(function(x){return'<div class="card"><div>'+esc(x.compliance)+'</div><div class="muted">'+esc(tp(x.created_at))+'｜'+esc(x.model)+'<br>情境：'+esc(x.context)+'</div></div>'}).join('')||'<p class="muted">還沒有套用紀錄。</p>')+'<p><button class="btn" id="soB">← 回長期命令</button></p>');$('soB').onclick=soList}});
 }catch(e){open('<h3>📌 長期命令</h3><p>⚠️ '+esc(e.message)+'</p>')}}
 window.__orders=soList;
 setTimeout(function(){if(typeof OWNER==='undefined'||!OWNER)return;var sh=$('sheet');if(!sh)return;new MutationObserver(function(){if(!sh.classList.contains('on')||!/📣 發號施令/.test(sh.innerHTML)||$('soBtn'))return;var b=document.createElement('p');b.innerHTML='<button class="btn" id="soBtn">📌 長期命令（每次排程都要遵守）</button>';sh.appendChild(b);$('soBtn').onclick=soList}).observe(sh,{childList:true})},2700);
 // lb2：點 AI（擁有者看得到 id 時）顯示 📚 學了 → 🧪 做了 → ✅ 通過（真實計數）
 setTimeout(function(){var sh=$('sheet');if(!sh)return;var busy=0;new MutationObserver(function(){if(busy||!sh.classList.contains('on')||$('labLine'))return;var m=sh.innerHTML.slice(0,600).match(/>(ag-\d{4})</);if(!m)return;busy=1;var p=document.createElement('p');p.id='labLine';p.className='muted';p.textContent='🧪 載入作品紀錄…';sh.appendChild(p);busy=0;
  api('degree','agent_lab',{id:m[1]}).then(function(d){p.innerHTML='📚 學了 <b>'+(d.learned||0)+'</b> 筆 → 🧪 做了 <b>'+(d.built||0)+'</b> 件 → ✅ 通過 <b>'+(d.passed||0)+'</b> 件 <a href="aivault-lab.html">實驗工廠</a><br>碩士需 2 件通過、博士需 5 件；沒有通過作品不能升級。'}).catch(function(){p.textContent=''})}).observe(sh,{childList:true})},2600);
 window.__plans={show:showPlans}})();
